using Godot;
using System;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class FluidBridgeOperations
{
    public void proxy(RefCounted owner,string key,string actorId,Transform3D pose,double radius,int layer,int mask){var owners=Map(owner,"proxy_owners");var proxies=owner.Get("proxies").As<RefCounted>();if(!owners.ContainsKey(key)){_collision.add(proxies,key,new SphereShape3D{Radius=(float)radius},Transform3D.Identity,layer,mask);owners[key]=actorId;}_collision.place(proxies,key,pose,true);}
    public void update_proxies(RefCounted owner,RefCounted controller,double time)
    {
        var proxies=owner.Get("proxies").As<RefCounted>();foreach(var id in Map(owner,"proxy_owners").Keys)_collision.place(proxies,id.AsString(),Transform3D.Identity,false);bool characters=false,deformables=false;var prototypes=Map(controller,"prototypes");var states=Map(controller,"states");foreach(var id in prototypes.Keys){int type=states[id].AsGodotDictionary()["type"].AsInt32();Settings config;if(type==9){var actor=Actor(controller,id.AsString());config=_animation.sampled_values(actor,controller.Call("_local",actor,time).AsDouble());characters|=Get(config,"fog_character_proxies",true).AsBool();deformables|=Get(config,"fog_character_proxies",true).AsBool();continue;}if(type==7){config=GD.Load<GDScript>("res://scripts/actors/physics/powder/powder_bridge.gd").Call("values",controller,id,time).AsGodotDictionary();characters|=Get(config,"powder_characters",true).AsBool();deformables|=Get(config,"powder_deformables",true).AsBool();continue;}if(type!=6)continue;config=values(controller,id.AsString(),time);characters|=config["fluid_characters"].AsBool();deformables|=config["fluid_deformables"].AsBool();}
        if(characters){var model=Object(controller,"_model");foreach(var value in model.Get("actors").AsGodotArray()){var actor=value.As<Resource>();string id=actor.Get("id").AsString();var clip=model.Call("clip_for_actor_id",id).As<Resource>();if(clip==null||!_clips.contains_time(clip,time))continue;var settings=_settings.sample(actor,_clips.local_time(clip,time));var bones=Get(actor.Get("values").AsGodotDictionary(),"rig_bones",new GArray()).AsGodotArray();for(int i=0;i<Math.Min(128,bones.Count);i++){var pose=controller.Call("bone_world",id,bones[i].AsGodotDictionary()["name"].AsString(),time).AsTransform3D();proxy(owner,id+":"+i,id,pose,.08,settings["layer"].AsInt32(),settings["mask"].AsInt32());}}}
        if(deformables)foreach(var id in states.Keys){var state=states[id].AsGodotDictionary();if(!state["active"].AsBool()||state["type"].AsInt32() is not (1 or 4 or 5))continue;var actor=Actor(controller,id.AsString());var settings=_settings.sample(actor,controller.Call("_local",actor,time).AsDouble());var points=state["points"].AsVector3Array();for(int i=0;i<points.Length;i++)proxy(owner,id.AsString()+":p"+i,id.AsString(),new Transform3D(Basis.Identity,points[i]),.06,settings["layer"].AsInt32(),settings["mask"].AsInt32());}
    }
    public void step(RefCounted owner,RefCounted controller,string id,Settings state,Settings config,double time,double dt)
    {
        var settings=values(controller,id,time);var compute=owner.Get("compute").AsGodotObject();if(compute==null||!compute.Call("available").AsBool())settings["budget"]=Math.Min(settings["budget"].AsInt32(),256);if(Get(state,"fluid_error","").AsString().Length>0)return;var pose=source(controller,id,config,time);var prototype=Map(controller,"prototypes")[id].AsGodotDictionary();var previous=source(controller,id,config,time-dt/Math.Max(.001,prototype["clip"].As<Resource>().Get("playback_speed").AsDouble()));var inherited=config["inherit_velocity"].AsBool()?(pose.Origin-previous.Origin)/(float)dt:Vector3.Zero;double at=controller.Call("_local",prototype["actor"],time).AsDouble();Solver().Call("emit",state,settings,pose,inherited+config["velocity"].AsVector3(),at,dt);var impulses=controller.Call("_events",config,at,dt).AsGodotDictionary();var collide=Callable.From<Vector3,Vector3,float,Vector3,Settings>((from,to,radius,velocity)=>
        {
            if(!config["collision"].AsBool())return new Settings{["position"]=to,["hits"]=new GArray()};var result=_collision.point_motion(controller.Get("world").As<RefCounted>(),id,from,to,radius,config["layer"].AsInt32(),config["mask"].AsInt32(),new GArray());var hits=result["hits"].AsGodotArray();foreach(var value in hits){var hit=value.AsGodotDictionary();var other=Object(controller,"debris").Call("lookup",controller,hit["actor"].AsString()).AsGodotDictionary();var speed=Get(other,"v",Vector3.Zero).AsVector3();if(other.Count>0)speed+=Get(other,"w",Vector3.Zero).AsVector3().Cross(hit["point"].AsVector3()-other["pose"].AsTransform3D().Origin);hit["velocity"]=speed;}if(settings["fluid_characters"].AsBool()||settings["fluid_deformables"].AsBool()){var secondary=_collision.point_motion(owner.Get("proxies").As<RefCounted>(),id,from,result["position"].AsVector3(),radius,config["layer"].AsInt32(),config["mask"].AsInt32(),new GArray());foreach(var value in secondary["hits"].AsGodotArray()){var hit=value.AsGodotDictionary();hit["actor"]=Get(Map(owner,"proxy_owners"),hit["actor"].AsString(),"");hits.Add(hit);}result["position"]=secondary["position"];}return result;
        });var acceleration=controller.Call("_gravity",config).AsVector3()+impulses["force"].AsVector3()/(float)Math.Max(1,settings["fluid_density"].AsDouble());Solver().Call("step",state,settings,acceleration,impulses["impulse"],dt,collide,compute==null?default(Variant):Variant.From(compute));var velocities=state["velocities"].AsVector3Array();float damping=(float)Math.Exp(-config["damping"].AsDouble()*dt);for(int i=0;i<velocities.Length;i++)velocities[i]*=damping;state["velocities"]=velocities;state["pose"]=pose;
    }
}
